<section class="container section-top"><?php ff_heading('classes','Find a time. Choose your focus. Make room for movement.'); ?><div class="notice compact"><?=ff_icon('bolt')?><p><?=e(t('All times are shown in Europe/Skopje.'))?></p></div><form class="filter-bar wrap" method="get"><input type="hidden" name="page" value="classes"><input type="hidden" name="lang" value="<?=e($lang)?>"><label><span><?=e(t('search'))?></span><input name="q" value="<?=e($_GET['q']??'')?>" maxlength="100"></label><label><span><?=e(t('date'))?></span><input name="date" type="date" value="<?=e($_GET['date']??'')?>"></label><label><span><?=e(t('category'))?></span><select name="category"><option value=""><?=e(t('all_categories'))?></option><?php foreach($categories??[] as $cat): $v=is_array($cat)?$cat['category']:$cat; ?><option <?=($_GET['category']??'')===$v?'selected':''?> value="<?=e($v)?>"><?=e(t($v))?></option><?php endforeach ?></select></label><label><span><?=e(t('trainer'))?></span><select name="trainer_id"><option value=""><?=e(t('all_trainers'))?></option><?php foreach($trainers??[] as $trainer): ?><option value="<?=e($trainer['id'])?>" <?=($_GET['trainer_id']??'')==(string)$trainer['id']?'selected':''?>><?=e($trainer['title']??$trainer['name'])?></option><?php endforeach ?></select></label><label><span><?=e(t('difficulty'))?></span><select name="level"><option value=""><?=e(t('all_levels'))?></option><?php foreach(['beginner','intermediate','all_levels'] as $v): ?><option value="<?=e($v)?>" <?=($_GET['level']??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach ?></select></label><label><span><?=e(t('availability'))?></span><select name="availability"><?php foreach([''=>'all_sessions','available'=>'available','full'=>'full','cancelled'=>'cancelled','past'=>'past'] as $v=>$label): ?><option value="<?=e($v)?>" <?=($_GET['availability']??'')===$v?'selected':''?>><?=e(t($label))?></option><?php endforeach ?></select></label><button class="button dark" type="submit"><?=e(t('filter'))?></button><a class="text-link" href="<?=e(url('classes'))?>"><?=e(t('clear_filters'))?></a></form><div class="results-caption"><p><?=count($items??[])?> <?=e(t('sessions'))?></p><div class="view-toggle" role="group" aria-label="<?=e(t('schedule_view'))?>"><button class="selected" data-schedule-view="list" aria-pressed="true" type="button"><?=e(t('list'))?></button><button data-schedule-view="calendar" aria-pressed="false" type="button"><?=e(t('calendar'))?></button></div></div><div class="class-list" data-schedule-list><?php foreach($items??[] as $session)ff_class_row($session); ?></div><?php
$monthInput=$_GET['month']??''; $monthInput=is_string($monthInput)&&preg_match('/^20[0-9]{2}-(0[1-9]|1[0-2])$/',$monthInput)?$monthInput.'-01':($_GET['date']??'now'); $calendarAnchor=new DateTimeImmutable($monthInput,new DateTimeZone('Europe/Skopje'));
$calendarMonth=$calendarAnchor->modify('first day of this month')->setTime(0,0);
$calendarStart=$calendarMonth->modify('monday this week');
$calendarEnd=$calendarMonth->modify('last day of this month')->modify('sunday this week');
$calendarEvents=[];
foreach($items??[] as $event){$eventStart=new DateTimeImmutable($event['starts_at']??$event['start_at'],new DateTimeZone('UTC'));$eventDay=$eventStart->setTimezone(new DateTimeZone('Europe/Skopje'))->format('Y-m-d');$calendarEvents[$eventDay][]=$event;}
?>
<section data-schedule-calendar hidden class="calendar-view"><div class="calendar-heading"><a class="button secondary small" href="<?=e(url('classes',['month'=>$calendarMonth->modify('-1 month')->format('Y-m'),'period'=>'all','view'=>'calendar']))?>">← <?=e(t('previous_month'))?></a><h2><?=e($calendarMonth->format('m / Y'))?></h2><a class="button secondary small" href="<?=e(url('classes',['month'=>$calendarMonth->modify('+1 month')->format('Y-m'),'period'=>'all','view'=>'calendar']))?>"><?=e(t('next_month'))?> →</a></div><p class="section-note"><?=e(t('Calendar shows the sessions matching your current filters. The list view provides the same information.'))?></p><div class="calendar-scroll"><div class="month-grid"><?php foreach(['monday','tuesday','wednesday','thursday','friday','saturday','sunday'] as $weekday): ?><div class="calendar-weekday"><?=e(t($weekday))?></div><?php endforeach ?><?php for($day=$calendarStart;$day<=$calendarEnd;$day=$day->modify('+1 day')): $dayKey=$day->format('Y-m-d'); ?><div class="calendar-day <?=$day->format('m')!==$calendarMonth->format('m')?'outside-month':''?> <?=$dayKey===(new DateTimeImmutable('now',new DateTimeZone('Europe/Skopje')))->format('Y-m-d')?'today':''?>"><span class="calendar-day-number"><?=e($day->format('d'))?></span><?php foreach($calendarEvents[$dayKey]??[] as $event): ?><a href="<?=e(url('class',['id'=>$event['id']]))?>" class="month-event"><strong><?=e(local_time($event['starts_at']??$event['start_at'],'H:i'))?></strong><span><?=e($event['title'])?></span><small><?=e(t($event['status']??'scheduled'))?></small></a><?php endforeach ?></div><?php endfor ?></div></div></section><?php if(empty($items))ff_empty('No classes match your filters.','classes'); ?><div class="date-navigation"><a class="button secondary small" href="<?=e(url('classes',['date'=>ff_local_date('-1 day')]))?>">← <?=e(t('previous_day'))?></a><a class="text-link" href="<?=e(url('classes',['date'=>(new DateTimeImmutable('now',new DateTimeZone('Europe/Skopje')))->format('Y-m-d')]))?>"><?=e(t('today'))?></a><a class="button secondary small" href="<?=e(url('classes',['date'=>ff_local_date('+1 day')]))?>"><?=e(t('next_day'))?> →</a></div></section>
